 function shoot(){let target=nearest();if(!target)return;let a=Math.atan2(target.y-player.y,target.x-player.x),speed=550;bullets.push({x:player.x+Math.cos(a)*13,y:player.y+Math.sin(a)*13,vx:Math.cos(a)*speed,vy:Math.sin(a)*speed,r:3,life:.8,damage:player.damage});shotTimer=player.fireRate;for(let i=0;i<3;i++)particles.push({x:player.x+Math.cos(a)*13,y:player.y+Math.sin(a)*13,vx:rand(-35,35)+Math.cos(a)*rand(25,75),vy:rand(-35,35)+Math.sin(a)*rand(25,75),life:rand(.08,.2),max:.2,color:'#f7d88e',size:rand(1,2.5)})}
 function hurt(amount){if(player.invuln>0)return;player.hp-=amount;player.invuln=.35;shake=7;setHud();if(player.hp<=0){player.hp=0;setHud();endGame()}}
 function makeDrop(x,y,type){drops.push({x,y,type,life:14,r:type==='med'?7:5,phase:rand(0,6)})}
