 for(let i=enemies.length-1;i>=0;i--){let e=enemies[i],d=dist(e,player),a=Math.atan2(player.y-e.y,player.x-e.x);e.flash=Math.max(0,e.flash-dt);if(e.type==='spitter'&&d<245){e.attack-=dt;if(e.attack<=0){let s=190;enemyShots.push({x:e.x,y:e.y,vx:Math.cos(a)*s,vy:Math.sin(a)*s,r:4,life:2,damage:e.damage});e.attack=rand(1.5,2.4)}if(d>145){e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt}}else{e.x+=Math.cos(a)*e.speed*dt;e.y+=Math.sin(a)*e.speed*dt}if(d<e.r+player.r+2){e.attack-=dt;if(e.attack<=0){hurt(e.damage);e.attack=e.type==='brute'?1.1:.8}let push=Math.max(0,e.r+player.r-d);e.x-=Math.cos(a)*push*.3;e.y-=Math.sin(a)*push*.3}}
 for(let i=bullets.length-1;i>=0;i--){let b=bullets[i];b.x+=b.vx*dt;b.y+=b.vy*dt;b.life-=dt;let hit=false;for(let j=enemies.length-1;j>=0;j--){let e=enemies[j];if(Math.hypot(e.x-b.x,e.y-b.y)<e.r+b.r){e.hp-=b.damage;e.flash=.1;hit=true;for(let k=0;k<4;k++)particles.push({x:b.x,y:b.y,vx:rand(-80,80),vy:rand(-80,80),life:.22,max:.22,color:e.color,size:rand(1,3)});if(e.hp<=0){kills++;scrap+=e.value;makeDrop(e.x,e.y,Math.random()<.09?'med':'scrap');for(let k=0;k<10;k++)particles.push({x:e.x,y:e.y,vx:rand(-110,110),vy:rand(-110,110),life:rand(.2,.48),max:.48,color:e.color,size:rand(2,4)});enemies.splice(j,1);setHud()}break}}if(hit||b.life<=0||b.x<0||b.x>W||b.y<0||b.y>H)bullets.splice(i,1)}
